<?php $e = static fn($value) => htmlspecialchars((string)$value, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rconnect Account Notice</title>
<style>body{margin:0;background:#f6f8ec;color:#2e4836;font:16px/1.65 Arial,sans-serif}.account-card{max-width:650px;margin:30px auto;padding:24px;background:#fffdf8;border:1px solid #cdd9b5;border-radius:20px}h1{font-size:24px;color:#295738}.status{font-weight:bold;color:#9b352d}.notice{padding:16px;border:1px solid #e5e0a4;border-radius:12px;background:#f9f4da}textarea{width:100%;box-sizing:border-box;padding:12px;border:1px solid #cdd9b5;border-radius:10px;font:inherit}button,a{display:inline-block;padding:10px 16px;border:1px solid #cdd9b5;border-radius:10px;color:#295738;background:#fff;text-decoration:none}button{background:#295738;color:#fff;cursor:pointer}small{color:#718071}@media(max-width:700px){.account-card{margin:16px;padding:18px}}</style></head><body><main class="account-card">
<h1>Rconnect Account Restriction</h1><p><?= $e($account['full_name']) ?> · <?= $e($account['passenger_code']) ?></p><p class="status"><?= $e($account['effective_account_status']) ?></p>
<div class="notice" role="status"><?= $e(PassengerAccountService::notice($account)) ?></div>
<?php if (!empty($account['status_reason'])): ?><p><strong>Reason:</strong> <?= $e($account['status_reason']) ?></p><?php endif; ?>
<?php if (!empty($_SESSION['account_appeal_notice'])): ?><p role="status"><?= $e($_SESSION['account_appeal_notice']) ?></p><?php unset($_SESSION['account_appeal_notice']); endif; ?>
<h2>Submit an appeal</h2><p>Your QR code and normal passenger services are unavailable while this restriction applies. An appeal does not automatically change your account status.</p>
<form method="post" action="<?= $e(passenger_url('account/appeal')) ?>"><input type="hidden" name="_csrf" value="<?= $e(passenger_csrf_token()) ?>"><label for="appealMessage">Explain why your account should be reviewed</label><textarea id="appealMessage" name="message" rows="5" minlength="10" maxlength="2000" required></textarea><button type="submit">Submit Appeal</button></form>
<?php foreach ($appeals as $appeal): ?><hr><strong><?= $e($appeal['status']) ?></strong> <small><?= $e($appeal['created_at']) ?></small><p><?= $e($appeal['message']) ?></p><?php if ($appeal['review_note']): ?><p>Administrator response: <?= $e($appeal['review_note']) ?></p><?php endif; ?><?php endforeach; ?>
<p><a href="<?= $e(passenger_url('logout')) ?>">Log Out</a></p></main></body></html>
